values ('M72603', 7, 'HSK 7–9 · HSK 3.0 загвар шалгалт №3 (全真模拟)', 91, 180, true, '[{"skill": "listening", "audio_url": "/mock-tests/m72603/listening.mp3", "time_min": 30, "parts": [{"part": 1, "range": [1, 10], "q_type": "judge", "desc": "Мэдээ — √/×"}, {"part": 2, "range": [11, 22], "q_type": "choice", "desc": "Яриа — сонгох/нөхөх"}, {"part": 3, "range": [23, 40], "q_type": "choice", "desc": "Лекц/өгүүлэл — сонгох/нөхөх"}]}, {"skill": "reading", "audio_url": null, "time_min": 60, "parts": [{"part": 1, "range": [41, 68], "q_type": "choice", "desc": "Эхийн ойлгоц — сонгох"}, {"part": 2, "range": [69, 73], "q_type": "choice", "desc": "Догол мөр эрэмбэлэх"}, {"part": 3, "range": [74, 87], "q_type": "essay", "desc": "Асуултад богино хариулах"}]}, {"skill": "writing", "audio_url": null, "time_min": 90, "parts": [{"part": 1, "range": [88, 88], "q_type": "essay_picture", "desc": "Диаграмм тайлбарлах (15 мин)"}, {"part": 2, "range": [89, 89], "q_type": "essay", "desc": "Сэдэвт эссэ (40 мин)"}, {"part": 3, "range": [90, 91], "q_type": "essay", "desc": "Бичгийн орчуулга (35 мин)"}]}]'::jsonb, true)
