insert into public.mock_test_questions (test_id, skill, part, q_no, q_type, stem, options, correct_answer, autograde, points, audio_url, image_url, needs_image, tags, explanation_mn, audio_start_sec, audio_end_sec, audio_transcript, tutor_note) values
('M72603','listening',1,1,'judge','春运以春节为中心，共20天左右。',null,'×','auto',1,'/mock-tests/m72603/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Эхний догол мөрөнд «前后共40天左右» гэсэн. Асуултад «20天» гэснээр буруу, тиймээс ×.',86.62,283.39,'春运，即春节运输，是中国在农历春节前后发生的一种大规模的高交通运输压力的现象。以春节为中心，前后共40天左右。一般意义上的春运，不包括国际交通。
早在1954年，中国就首次明确春运为春节前后一个月。1980年3月，“春运”一词第一次登上《人民日报》。这一大规模的人口流动也被大众广泛关注，成为中国独具魅力的一道风景。
随着改革开放的发展，越来越多的人选择离开家乡，外出求学、工作。每年春节期间，人们都会集中返乡与家人团聚。如此庞大的人群同时出行，就形成了堪称“人类史上最大规模迁移”的春运。春运的客流量有多大？据统计，2024年春运全国铁路发送旅客达到4.8亿人次，相当于让北美洲的居民集体搬了一次家。
无论是在外奋斗拼搏了一年的游子，还是守候在老家的亲人，春节团聚是他们每年都期盼的事。人们克服种种困难参加春运，回到家乡，与亲人团圆的同时也汲取力量。从这个意义上讲，有春节起，便有了“春运”。','{"transcript": [{"zh": "春运，即春节运输，是中国在农历春节前后发生的一种大规模的高交通运输压力的现象。以春节为中心，前后共40天左右。一般意义上的春运，不包括国际交通。", "mn": "«Чуньюнь» буюу Хаврын баярын тээвэр нь Хятадад цагаан сарын өмнө хойно болдог, тээврийн ачаалал асар их болдог үзэгдэл. Хаврын баярыг төвд нь авч өмнө хойно нийт 40 орчим хоног үргэлжилнэ. Ерөнхийдөө чуньюнь олон улсын тээврийг оруулдаггүй."}, {"zh": "早在1954年，中国就首次明确春运为春节前后一个月。1980年3月，“春运”一词第一次登上《人民日报》。这一大规模的人口流动也被大众广泛关注，成为中国独具魅力的一道风景。", "mn": "1954 онд Хятад улс чуньюньг баярын өмнө хойно нийт нэг сар гэж анх тодорхойлсон. 1980 оны 3-р сард «чуньюнь» гэдэг үг анх «Ард түмний өдрийн сонин»-д гарсан. Энэ том хэмжээний хүн урсгал олны анхаарлыг татаж, Хятадын өвөрмөц сонирхолтой нэгэн үзэгдэл болсон."}, {"zh": "随着改革开放的发展，越来越多的人选择离开家乡，外出求学、工作。每年春节期间，人们都会集中返乡与家人团聚。如此庞大的人群同时出行，就形成了堪称“人类史上最大规模迁移”的春运。春运的客流量有多大？据统计，2024年春运全国铁路发送旅客达到4.8亿人次，相当于让北美洲的居民集体搬了一次家。", "mn": "Шинэчлэл нээлттэй бодлого хөгжихийн хирээр улам олон хүн нутгаасаа гарч сурч, ажиллах болсон. Хаврын баяраар хүмүүс бөөнөөрөө гэртээ буцаж гэр бүлтэйгээ уулздаг. Ийм асар олон хүн нэгэн зэрэг явснаар «хүн төрөлхтний түүхэн дэх хамгийн том нүүдэл» гэж хэлэмээр чуньюнь бүрдсэн. Зорчигчийн урсгал хэр их вэ? Статистикаар 2024 оны чуньюнь-д улсын төмөр замаар 480 сая удаагийн зорчигч тээвэрлэсэн нь Хойд Америкийн оршин суугчдыг бүгдийг нь нэг удаа нүүлгэсэнтэй тэнцэнэ."}, {"zh": "无论是在外奋斗拼搏了一年的游子，还是守候在老家的亲人，春节团聚是他们每年都期盼的事。人们克服种种困难参加春运，回到家乡，与亲人团圆的同时也汲取力量。从这个意义上讲，有春节起，便有了“春运”。", "mn": "Нэг жил гадаа хөдөлмөрлөсөн хүн ч, төрсөн нутагтаа хүлээсэн хамаатан садан ч Хаврын баярын уулзалтыг жил бүр хүсэн хүлээдэг. Хүмүүс олон бэрхшээлийг даван чуньюньд оролцож, нутагтаа ирж ойр дотныхонтойгоо уулзахын зэрэгцээ хүч тэнхээ авдаг. Ийм утгаар Хаврын баяр байх үеэс «чуньюнь» байсан гэж хэлж болно."}], "key": "以春节为中心，前后共40天左右。", "keyMn": "Хаврын баярыг төвд нь авч өмнө хойно нийт 40 орчим хоног", "why": "Эхний догол мөрөнд «前后共40天左右» гэсэн. Асуултад «20天» гэснээр буруу, тиймээс ×.", "tip": "Тоо, хугацааг сонсоход тэмдэглэ: 40 ≠ 20.", "words": [{"zh": "春运", "pinyin": "chūnyùn", "mn": "Хаврын баярын тээвэр"}, {"zh": "国际交通", "pinyin": "guójì jiāotōng", "mn": "олон улсын тээвэр"}, {"zh": "返乡", "pinyin": "fǎnxiāng", "mn": "нутаг руугаа буцах"}]}'::jsonb),
('M72603','listening',1,2,'judge','一般意义上的春运不包括国际交通。',null,'√','auto',1,'/mock-tests/m72603/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Эхний догол мөрийн төгсгөлд «不包括国际交通» гэж шууд хэлсэн тул √.',86.62,283.39,'春运，即春节运输，是中国在农历春节前后发生的一种大规模的高交通运输压力的现象。以春节为中心，前后共40天左右。一般意义上的春运，不包括国际交通。
早在1954年，中国就首次明确春运为春节前后一个月。1980年3月，“春运”一词第一次登上《人民日报》。这一大规模的人口流动也被大众广泛关注，成为中国独具魅力的一道风景。
随着改革开放的发展，越来越多的人选择离开家乡，外出求学、工作。每年春节期间，人们都会集中返乡与家人团聚。如此庞大的人群同时出行，就形成了堪称“人类史上最大规模迁移”的春运。春运的客流量有多大？据统计，2024年春运全国铁路发送旅客达到4.8亿人次，相当于让北美洲的居民集体搬了一次家。
无论是在外奋斗拼搏了一年的游子，还是守候在老家的亲人，春节团聚是他们每年都期盼的事。人们克服种种困难参加春运，回到家乡，与亲人团圆的同时也汲取力量。从这个意义上讲，有春节起，便有了“春运”。','{"transcript": [{"zh": "春运，即春节运输，是中国在农历春节前后发生的一种大规模的高交通运输压力的现象。以春节为中心，前后共40天左右。一般意义上的春运，不包括国际交通。", "mn": "«Чуньюнь» буюу Хаврын баярын тээвэр нь Хятадад цагаан сарын өмнө хойно болдог, тээврийн ачаалал асар их болдог үзэгдэл. Хаврын баярыг төвд нь авч өмнө хойно нийт 40 орчим хоног үргэлжилнэ. Ерөнхийдөө чуньюнь олон улсын тээврийг оруулдаггүй."}, {"zh": "早在1954年，中国就首次明确春运为春节前后一个月。1980年3月，“春运”一词第一次登上《人民日报》。这一大规模的人口流动也被大众广泛关注，成为中国独具魅力的一道风景。", "mn": "1954 онд Хятад улс чуньюньг баярын өмнө хойно нийт нэг сар гэж анх тодорхойлсон. 1980 оны 3-р сард «чуньюнь» гэдэг үг анх «Ард түмний өдрийн сонин»-д гарсан. Энэ том хэмжээний хүн урсгал олны анхаарлыг татаж, Хятадын өвөрмөц сонирхолтой нэгэн үзэгдэл болсон."}, {"zh": "随着改革开放的发展，越来越多的人选择离开家乡，外出求学、工作。每年春节期间，人们都会集中返乡与家人团聚。如此庞大的人群同时出行，就形成了堪称“人类史上最大规模迁移”的春运。春运的客流量有多大？据统计，2024年春运全国铁路发送旅客达到4.8亿人次，相当于让北美洲的居民集体搬了一次家。", "mn": "Шинэчлэл нээлттэй бодлого хөгжихийн хирээр улам олон хүн нутгаасаа гарч сурч, ажиллах болсон. Хаврын баяраар хүмүүс бөөнөөрөө гэртээ буцаж гэр бүлтэйгээ уулздаг. Ийм асар олон хүн нэгэн зэрэг явснаар «хүн төрөлхтний түүхэн дэх хамгийн том нүүдэл» гэж хэлэмээр чуньюнь бүрдсэн. Зорчигчийн урсгал хэр их вэ? Статистикаар 2024 оны чуньюнь-д улсын төмөр замаар 480 сая удаагийн зорчигч тээвэрлэсэн нь Хойд Америкийн оршин суугчдыг бүгдийг нь нэг удаа нүүлгэсэнтэй тэнцэнэ."}, {"zh": "无论是在外奋斗拼搏了一年的游子，还是守候在老家的亲人，春节团聚是他们每年都期盼的事。人们克服种种困难参加春运，回到家乡，与亲人团圆的同时也汲取力量。从这个意义上讲，有春节起，便有了“春运”。", "mn": "Нэг жил гадаа хөдөлмөрлөсөн хүн ч, төрсөн нутагтаа хүлээсэн хамаатан садан ч Хаврын баярын уулзалтыг жил бүр хүсэн хүлээдэг. Хүмүүс олон бэрхшээлийг даван чуньюньд оролцож, нутагтаа ирж ойр дотныхонтойгоо уулзахын зэрэгцээ хүч тэнхээ авдаг. Ийм утгаар Хаврын баяр байх үеэс «чуньюнь» байсан гэж хэлж болно."}], "key": "一般意义上的春运，不包括国际交通。", "keyMn": "Ерөнхийдөө чуньюнь олон улсын тээврийг оруулдаггүй", "why": "Эхний догол мөрийн төгсгөлд «不包括国际交通» гэж шууд хэлсэн тул √."}'::jsonb),
('M72603','listening',1,3,'judge','1981年，“春运”一词第一次登上《光明日报》。',null,'×','auto',1,'/mock-tests/m72603/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Эх нь 1980 он, 《人民日报》. Асуултад 1981 он, 《光明日报》 гэсэн хоёр газар андуурсан тул ×.',86.62,283.39,'春运，即春节运输，是中国在农历春节前后发生的一种大规模的高交通运输压力的现象。以春节为中心，前后共40天左右。一般意义上的春运，不包括国际交通。
早在1954年，中国就首次明确春运为春节前后一个月。1980年3月，“春运”一词第一次登上《人民日报》。这一大规模的人口流动也被大众广泛关注，成为中国独具魅力的一道风景。
随着改革开放的发展，越来越多的人选择离开家乡，外出求学、工作。每年春节期间，人们都会集中返乡与家人团聚。如此庞大的人群同时出行，就形成了堪称“人类史上最大规模迁移”的春运。春运的客流量有多大？据统计，2024年春运全国铁路发送旅客达到4.8亿人次，相当于让北美洲的居民集体搬了一次家。
无论是在外奋斗拼搏了一年的游子，还是守候在老家的亲人，春节团聚是他们每年都期盼的事。人们克服种种困难参加春运，回到家乡，与亲人团圆的同时也汲取力量。从这个意义上讲，有春节起，便有了“春运”。','{"transcript": [{"zh": "春运，即春节运输，是中国在农历春节前后发生的一种大规模的高交通运输压力的现象。以春节为中心，前后共40天左右。一般意义上的春运，不包括国际交通。", "mn": "«Чуньюнь» буюу Хаврын баярын тээвэр нь Хятадад цагаан сарын өмнө хойно болдог, тээврийн ачаалал асар их болдог үзэгдэл. Хаврын баярыг төвд нь авч өмнө хойно нийт 40 орчим хоног үргэлжилнэ. Ерөнхийдөө чуньюнь олон улсын тээврийг оруулдаггүй."}, {"zh": "早在1954年，中国就首次明确春运为春节前后一个月。1980年3月，“春运”一词第一次登上《人民日报》。这一大规模的人口流动也被大众广泛关注，成为中国独具魅力的一道风景。", "mn": "1954 онд Хятад улс чуньюньг баярын өмнө хойно нийт нэг сар гэж анх тодорхойлсон. 1980 оны 3-р сард «чуньюнь» гэдэг үг анх «Ард түмний өдрийн сонин»-д гарсан. Энэ том хэмжээний хүн урсгал олны анхаарлыг татаж, Хятадын өвөрмөц сонирхолтой нэгэн үзэгдэл болсон."}, {"zh": "随着改革开放的发展，越来越多的人选择离开家乡，外出求学、工作。每年春节期间，人们都会集中返乡与家人团聚。如此庞大的人群同时出行，就形成了堪称“人类史上最大规模迁移”的春运。春运的客流量有多大？据统计，2024年春运全国铁路发送旅客达到4.8亿人次，相当于让北美洲的居民集体搬了一次家。", "mn": "Шинэчлэл нээлттэй бодлого хөгжихийн хирээр улам олон хүн нутгаасаа гарч сурч, ажиллах болсон. Хаврын баяраар хүмүүс бөөнөөрөө гэртээ буцаж гэр бүлтэйгээ уулздаг. Ийм асар олон хүн нэгэн зэрэг явснаар «хүн төрөлхтний түүхэн дэх хамгийн том нүүдэл» гэж хэлэмээр чуньюнь бүрдсэн. Зорчигчийн урсгал хэр их вэ? Статистикаар 2024 оны чуньюнь-д улсын төмөр замаар 480 сая удаагийн зорчигч тээвэрлэсэн нь Хойд Америкийн оршин суугчдыг бүгдийг нь нэг удаа нүүлгэсэнтэй тэнцэнэ."}, {"zh": "无论是在外奋斗拼搏了一年的游子，还是守候在老家的亲人，春节团聚是他们每年都期盼的事。人们克服种种困难参加春运，回到家乡，与亲人团圆的同时也汲取力量。从这个意义上讲，有春节起，便有了“春运”。", "mn": "Нэг жил гадаа хөдөлмөрлөсөн хүн ч, төрсөн нутагтаа хүлээсэн хамаатан садан ч Хаврын баярын уулзалтыг жил бүр хүсэн хүлээдэг. Хүмүүс олон бэрхшээлийг даван чуньюньд оролцож, нутагтаа ирж ойр дотныхонтойгоо уулзахын зэрэгцээ хүч тэнхээ авдаг. Ийм утгаар Хаврын баяр байх үеэс «чуньюнь» байсан гэж хэлж болно."}], "key": "1980年3月，“春运”一词第一次登上《人民日报》。", "keyMn": "1980 оны 3-р сард «чуньюнь» гэдэг үг анх «Ард түмний өдрийн сонин»-д гарсан", "why": "Эх нь 1980 он, 《人民日报》. Асуултад 1981 он, 《光明日报》 гэсэн хоёр газар андуурсан тул ×.", "trap": "Он ба сонины нэр хоёулаа солигдсон."}'::jsonb),
('M72603','listening',1,4,'judge','2024年春运全国铁路发送旅客达到4.8亿人次，相当于让北美洲的居民集体搬了一次家。',null,'√','auto',1,'/mock-tests/m72603/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Гурав дахь догол мөрөнд яг энэ өгүүлбэр байгаа тул √.',86.62,283.39,'春运，即春节运输，是中国在农历春节前后发生的一种大规模的高交通运输压力的现象。以春节为中心，前后共40天左右。一般意义上的春运，不包括国际交通。
早在1954年，中国就首次明确春运为春节前后一个月。1980年3月，“春运”一词第一次登上《人民日报》。这一大规模的人口流动也被大众广泛关注，成为中国独具魅力的一道风景。
